package plugins

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"strings"

	"github.com/Aoody743/PowerLinux/internal/core"
)

// Admin rotation never accepts a password in a durable task input. New secrets
// are generated by the root Agent and remain in its encrypted private records.
type databaseAdminInput struct {
	InstanceID               string `json:"instance_id"`
	Command                  string `json:"command"`
	CurrentCredentialVersion string `json:"current_credential_version"`
	// Transient native IPC only; API tasks use databaseAdminRotateInput instead.
	Password string `json:"password,omitempty"`
}
type databaseAdminState struct {
	CurrentCredentialVersion string   `json:"current_credential_version"`
	State                    string   `json:"state"`
	AvailableActions         []string `json:"available_actions"`
}
type databaseAdminIntent struct {
	InstanceID, Engine, DataDir, Username string
	FromVersion, ToVersion                string
	State                                 string
}

func databaseAdminIntentID(i Instance) string { return "dbadmin_intent_" + i.ID }
func databaseAdminVersionID(i Instance, version string) string {
	return "dbadmin_" + i.ID + "_" + version
}
func newDatabaseAdminVersion() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}
func validDatabaseAdminVersion(v string) bool {
	b, err := hex.DecodeString(v)
	return err == nil && len(b) == 16
}
func (e *PrivilegedExecutor) validateDatabaseAdmin(raw json.RawMessage) error {
	var in databaseAdminInput
	if err := parse(raw, &in); err != nil {
		return err
	}
	if !validInstanceID(in.InstanceID) || len(in.InstanceID) > 70 {
		return failure("invalid_input", "Invalid managed SQL instance", 400)
	}
	if in.Password != "" && (in.Command != "rotate" || !validDatabaseAdminPassword(in.Password)) {
		return failure("invalid_input", "Custom password is accepted only for an administrator rotation", 400)
	}
	switch in.Command {
	case "inspect":
	case "initialize":
		if in.CurrentCredentialVersion != "" {
			return failure("invalid_input", "Legacy initialization requires an empty current version", 400)
		}
	case "rotate", "recover", "apply_pending":
		if !validDatabaseAdminVersion(in.CurrentCredentialVersion) {
			return failure("invalid_input", "Current credential version is required", 400)
		}
	default:
		return failure("invalid_input", "Unsupported administrator credential command", 400)
	}
	return nil
}
func (e *PrivilegedExecutor) loadDatabaseAdminIntent(i Instance) (*databaseAdminIntent, error) {
	var intent databaseAdminIntent
	err := e.load("private", databaseAdminIntentID(i), &intent)
	if core.ErrorCode(err) == "not_found" {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	if intent.InstanceID != i.ID || intent.Engine != i.PluginID || intent.DataDir != i.Paths.DataDir || !validDatabaseAdminVersion(intent.FromVersion) || !validDatabaseAdminVersion(intent.ToVersion) || intent.FromVersion == intent.ToVersion || (intent.State != "pending" && intent.State != "completed") {
		return nil, failure("ownership_invalid", "Administrator rotation intent does not match its instance", 412)
	}
	return &intent, nil
}
func (e *PrivilegedExecutor) ensureDatabaseAdminSettled(i Instance) error {
	intent, err := e.loadDatabaseAdminIntent(i)
	if err != nil {
		return err
	}
	if intent != nil && intent.State == "pending" {
		return failure("operation_recovery_required", "Administrator credential rotation requires explicit recovery", 409)
	}
	return nil
}

// A recovery connection can use only the canonical receipt or an immutable
// candidate explicitly named by this instance's protected pending intent.
func (e *PrivilegedExecutor) verifyDatabaseAdminCandidate(i Instance, candidate managedDatabaseCredential) error {
	var active managedDatabaseCredential
	if err := e.load("private", databasePrivateID(i), &active); err != nil {
		return failure("credential_unavailable", "Trusted administrator receipt is unavailable", 412)
	}
	if !candidate.Initialized || candidate.Engine != i.PluginID || candidate.DataDir != i.Paths.DataDir || candidate.Password == "" || candidate.Username != active.Username {
		return failure("credential_unavailable", "Administrator candidate does not match its trusted receipt", 412)
	}
	if candidate == active {
		return nil
	}
	intent, err := e.loadDatabaseAdminIntent(i)
	if err != nil {
		return err
	}
	if intent == nil || intent.State != "pending" || intent.Username != candidate.Username || (candidate.Version != intent.FromVersion && candidate.Version != intent.ToVersion) {
		return failure("credential_unavailable", "Administrator candidate has no protected pending intent", 412)
	}
	stored, err := e.loadDatabaseAdminVersion(i, candidate.Version, candidate.Username)
	if err != nil || stored != candidate {
		return failure("credential_unavailable", "Administrator candidate differs from its immutable version", 412)
	}
	return nil
}
func databaseAdminPublic(c managedDatabaseCredential, intent *databaseAdminIntent) databaseAdminState {
	result := databaseAdminState{CurrentCredentialVersion: c.Version, State: "active", AvailableActions: []string{"rotate"}}
	if c.Version == "" {
		result.State = "legacy_unversioned"
		result.AvailableActions = []string{"initialize"}
	}
	if intent != nil && intent.State == "pending" {
		result.State = "recovery_required"
		result.AvailableActions = []string{"recover", "apply_pending"}
	}
	return result
}
func (e *PrivilegedExecutor) loadDatabaseAdminVersion(i Instance, version, username string) (managedDatabaseCredential, error) {
	var c managedDatabaseCredential
	err := e.load("private", databaseAdminVersionID(i, version), &c)
	if err != nil {
		return c, err
	}
	if c.Version != version || c.Engine != i.PluginID || c.DataDir != i.Paths.DataDir || c.Username != username || !c.Initialized || c.Password == "" {
		return c, failure("ownership_invalid", "Administrator credential version is invalid", 412)
	}
	return c, nil
}
func (e *PrivilegedExecutor) saveDatabaseAdminVersion(i Instance, c managedDatabaseCredential) error {
	// Versions are immutable. The shared instance lock prevents concurrent writers.
	var old managedDatabaseCredential
	err := e.load("private", databaseAdminVersionID(i, c.Version), &old)
	if core.ErrorCode(err) != "not_found" {
		if err != nil {
			return err
		}
		return failure("revision_conflict", "Administrator credential version already exists", 412)
	}
	return e.save("private", databaseAdminVersionID(i, c.Version), c)
}
func (e *PrivilegedExecutor) databaseAdmin(ctx context.Context, raw json.RawMessage) (any, error) {
	if err := e.validateDatabaseAdmin(raw); err != nil {
		return nil, err
	}
	var in databaseAdminInput
	json.Unmarshal(raw, &in)
	unlock, err := e.lockContext(ctx, in.InstanceID)
	if err != nil {
		return nil, err
	}
	defer unlock()
	i, err := e.get(ctx, in.InstanceID, false)
	if err != nil {
		return nil, err
	}
	switch i.PluginID {
	case "postgresql", "mysql", "mysql-community", "mariadb":
	default:
		return nil, failure("unsupported_database", "Administrator rotation supports managed SQL engines only", 412)
	}
	if i.Ownership != "managed" || i.Status == "uninstalled" {
		return nil, failure("ownership_invalid", "Administrator rotation requires an active managed instance", 412)
	}
	if err = e.ensureInstallFinalized(ctx, i.ID); err != nil {
		return nil, err
	}
	var c managedDatabaseCredential
	if err = e.load("private", databasePrivateID(i), &c); err != nil {
		return nil, err
	}
	expectedUser := "root"
	if i.PluginID == "postgresql" {
		expectedUser = e.config.RunUser
	}
	if !c.Initialized || c.Engine != i.PluginID || c.DataDir != i.Paths.DataDir || c.Username != expectedUser || c.Password == "" || (c.Version != "" && !validDatabaseAdminVersion(c.Version)) {
		return nil, failure("credential_unavailable", "Trusted initialized administrator receipt is required", 412)
	}
	intent, err := e.loadDatabaseAdminIntent(i)
	if err != nil {
		return nil, err
	}
	if intent != nil && intent.Username != c.Username {
		return nil, failure("ownership_invalid", "Administrator rotation identity changed", 412)
	}
	if in.Command == "inspect" {
		return databaseAdminPublic(c, intent), nil
	}
	if err = e.ensureDatabaseReplicationDetached(ctx, i.ID); err != nil {
		return nil, err
	}
	if in.CurrentCredentialVersion != c.Version {
		return nil, failure("revision_conflict", "Administrator credential changed; reload before editing", 412)
	}
	pending := intent != nil && intent.State == "pending"
	if pending {
		if in.Command != "recover" && in.Command != "apply_pending" {
			return nil, failure("operation_recovery_required", "Administrator rotation requires explicit recovery", 409)
		}
		return e.recoverDatabaseAdmin(ctx, i, c, *intent, in.Command == "apply_pending")
	}
	switch in.Command {
	case "initialize":
		if c.Version != "" {
			return nil, failure("revision_conflict", "Administrator credential already has a version", 412)
		}
		c.Version, err = newDatabaseAdminVersion()
		if err != nil {
			return nil, err
		}
		if err = e.saveDatabaseAdminVersion(i, c); err != nil {
			return nil, err
		}
		if err = e.save("private", databasePrivateID(i), c); err != nil {
			return nil, err
		}
		return databaseAdminPublic(c, nil), nil
	case "rotate":
		if c.Version == "" {
			return nil, failure("credential_version_required", "Initialize the legacy credential version first", 409)
		}
		if in.Password != "" && in.Password == c.Password {
			return nil, failure("invalid_input", "Choose a different administrator password", 400)
		}
		next, stagedIntent, stageErr := e.stageDatabaseAdminRotation(i, c, in.Password)
		if stageErr != nil {
			return nil, stageErr
		}
		intent = &stagedIntent
		if err = e.alterDatabaseAdmin(ctx, i, c, next); err != nil {
			return nil, err
		}
		return e.commitDatabaseAdmin(ctx, i, next, *intent)
	default:
		return nil, failure("operation_not_pending", "No administrator rotation requires recovery", 409)
	}
}

// stageDatabaseAdminRotation requires the shared instance lock. Its durable
// intent is the boundary before any SQL mutation; recovery never needs the
// request's custom password once this function succeeds.
func (e *PrivilegedExecutor) stageDatabaseAdminRotation(i Instance, c managedDatabaseCredential, custom string) (managedDatabaseCredential, databaseAdminIntent, error) {
	var zero managedDatabaseCredential
	var empty databaseAdminIntent
	stored, loadErr := e.loadDatabaseAdminVersion(i, c.Version, c.Username)
	if loadErr != nil {
		return zero, empty, loadErr
	}
	if stored != c {
		return zero, empty, failure("ownership_invalid", "Active administrator receipt differs from its immutable version", 412)
	}
	var err error
	password := make([]byte, 32)
	if _, err = rand.Read(password); err != nil {
		return zero, empty, err
	}
	next := c
	next.Version, err = newDatabaseAdminVersion()
	if err != nil {
		return zero, empty, err
	}
	next.Password = base64.RawURLEncoding.EncodeToString(password)
	clear(password)
	if custom != "" {
		next.Password = custom
	}
	if err = e.saveDatabaseAdminVersion(i, next); err != nil {
		return zero, empty, err
	}
	intent := databaseAdminIntent{InstanceID: i.ID, Engine: i.PluginID, DataDir: i.Paths.DataDir, Username: c.Username, FromVersion: c.Version, ToVersion: next.Version, State: "pending"}
	if err = e.save("private", databaseAdminIntentID(i), intent); err != nil {
		return zero, empty, err
	}
	return next, intent, nil
}

func (e *PrivilegedExecutor) probeDatabaseAdmin(ctx context.Context, i Instance, c managedDatabaseCredential) bool {
	db, err := e.openManagedAdminCredential(ctx, i, c)
	if err != nil {
		return false
	}
	db.Close()
	return true
}
func (e *PrivilegedExecutor) alterDatabaseAdmin(ctx context.Context, i Instance, old, next managedDatabaseCredential) error {
	db, err := e.openManagedAdminCredential(ctx, i, old)
	if err != nil {
		return failure("operation_recovery_required", "Administrator rotation authentication failed; explicit recovery is required", 409)
	}
	defer db.Close()
	statement := "ALTER USER 'root'@'localhost' IDENTIFIED BY '" + strings.ReplaceAll(next.Password, "'", "''") + "'"
	if i.PluginID == "postgresql" {
		statement = "ALTER ROLE \"" + strings.ReplaceAll(old.Username, "\"", "\"\"") + "\" PASSWORD " + pgSQLLiteral(next.Password)
	}
	if _, err = db.ExecContext(ctx, statement); err != nil {
		return failure("operation_recovery_required", "Administrator rotation was not acknowledged; explicit recovery is required", 409)
	}
	return nil
}
func (e *PrivilegedExecutor) commitDatabaseAdmin(ctx context.Context, i Instance, next managedDatabaseCredential, intent databaseAdminIntent) (any, error) {
	return e.commitDatabaseAdminWithSave(ctx, i, next, intent, e.save)
}

// The persistence function is an in-memory test seam for a real filesystem
// failure at the SQL/receipt boundary. No request or policy can select it.
func (e *PrivilegedExecutor) commitDatabaseAdminWithSave(ctx context.Context, i Instance, next managedDatabaseCredential, intent databaseAdminIntent, save func(string, string, any) error) (any, error) {
	if !e.probeDatabaseAdmin(ctx, i, next) {
		return nil, failure("operation_recovery_required", "Pending administrator authentication was not verified; explicit recovery is required", 409)
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if err := save("private", databasePrivateID(i), next); err != nil {
		return nil, failure("operation_recovery_required", "Administrator rotation needs an explicit receipt recovery", 409)
	}
	intent.State = "completed"
	if err := save("private", databaseAdminIntentID(i), intent); err != nil {
		return nil, failure("operation_recovery_required", "Administrator rotation needs an explicit intent recovery", 409)
	}
	return databaseAdminPublic(next, nil), nil
}
func (e *PrivilegedExecutor) recoverDatabaseAdmin(ctx context.Context, i Instance, current managedDatabaseCredential, intent databaseAdminIntent, apply bool) (any, error) {
	if current.Version != intent.FromVersion && current.Version != intent.ToVersion {
		return nil, failure("revision_conflict", "Administrator rotation version differs from its intent", 412)
	}
	next, err := e.loadDatabaseAdminVersion(i, intent.ToVersion, intent.Username)
	if err != nil {
		return nil, err
	}
	// A SQL commit followed by cancellation/crash is recovered using the staged
	// credential. Never assume failure means ALTER did not commit.
	if e.probeDatabaseAdmin(ctx, i, next) {
		return e.commitDatabaseAdmin(ctx, i, next, intent)
	}
	if !apply {
		return nil, failure("operation_recovery_required", "Pending credential is not verified; explicitly apply the pending rotation after inspection", 409)
	}
	old, err := e.loadDatabaseAdminVersion(i, intent.FromVersion, intent.Username)
	if err != nil {
		return nil, err
	}
	if current.Version != intent.FromVersion || !e.probeDatabaseAdmin(ctx, i, old) {
		return nil, failure("operation_recovery_required", "Neither owned credential can safely authorize recovery", 409)
	}
	if err = e.alterDatabaseAdmin(ctx, i, old, next); err != nil {
		return nil, err
	}
	return e.commitDatabaseAdmin(ctx, i, next, intent)
}

func (m *Manager) databaseAdminBindings() []core.Binding {
	bindings := []core.Binding{}
	for _, command := range []string{"inspect", "initialize", "recover", "apply_pending"} {
		command := command
		fields := map[string]any{"instance_id": idSchema()}
		required := []string{"instance_id"}
		if command != "inspect" {
			fields["current_credential_version"] = map[string]any{"type": "string", "maxLength": 32}
			required = append(required, "current_credential_version")
		}
		resources := func(_ context.Context, _ core.Actor, raw json.RawMessage) ([]string, error) {
			var in databaseAdminInput
			if err := parse(raw, &in); err != nil {
				return nil, err
			}
			if !validInstanceID(in.InstanceID) {
				return nil, failure("invalid_input", "Invalid managed SQL instance", 400)
			}
			return []string{DatabaseResource(in.InstanceID, "")}, nil
		}
		binding := m.binding("managed_database_admin_"+command, "Inspect or explicitly rotate a trusted managed SQL administrator credential without exporting its secret", "databases:credentials", command == "inspect", obj(fields, required...), resources, func(ctx context.Context, a core.Actor, raw json.RawMessage) (core.ActionResult, error) {
			var in databaseAdminInput
			if err := parse(raw, &in); err != nil {
				return core.ActionResult{}, err
			}
			in.Command = command
			forward, _ := json.Marshal(in)
			resource, err := resources(ctx, a, raw)
			if err != nil {
				return core.ActionResult{}, err
			}
			if command != "inspect" {
				job, err := m.deps.Tasks.Submit(ctx, a, "database_admin_action", forward, resource)
				if err != nil {
					return core.ActionResult{}, err
				}
				id, _ := job["id"].(string)
				return core.ActionResult{Data: job, TaskID: id, Resources: resource}, nil
			}
			var output any
			if err = m.agentJSON(ctx, "database_admin_action", forward, &output); err != nil {
				return core.ActionResult{}, err
			}
			return core.ActionResult{Data: output, Resources: resource}, nil
		})
		binding.Action.Task = command != "inspect"
		bindings = append(bindings, binding)
	}
	return append(bindings, m.databaseAdminPasswordBindings()...)
}
